<?php session_start(); require_once 'db.php'; require_once 'auth_guard.php'; require_role('admin'); audit($pdo,(int)$_SESSION['user_id'],'Viewed audit logs'); $logs=$pdo->query('SELECT a.id,u.name AS user_name,a.action,a.created_at FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 200')->fetchAll(); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Audit Logs</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="container py-4"><h1>Audit Logs</h1><a class="btn btn-primary mb-3" href="dashboard.php">Dashboard</a><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>ID</th><th>User</th><th>Action</th><th>Date/Time</th></tr></thead><tbody><?php foreach($logs as $l): ?><tr><td><?=h($l['id'])?></td><td><?=h($l['user_name']??'Deleted user')?></td><td><?=h($l['action'])?></td><td><?=h($l['created_at'])?></td></tr><?php endforeach; ?></tbody></table></div></body></html>
